WITH cleaned AS (SELECT id, customer_id, balance, opened_date, status, ROUND(balance * 1.07, 2) AS adjusted_balance FROM accounts WHERE opened_date >= TO_DATE('2023-05-18')) SELECT *, LAST_VALUE(adjusted_balance, TRUE) OVER (PARTITION BY customer_id ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_adjusted_balance, AVG(balance) OVER (PARTITION BY customer_id) AS customer_id_avg_balance, NTILE(3) OVER (ORDER BY balance DESC, id) AS balance_bucket, ROW_NUMBER() OVER w_part AS event_seq, FIRST_VALUE(status, TRUE) OVER w_grp AS first_known_status FROM cleaned WINDOW w_part AS (PARTITION BY customer_id, status ORDER BY adjusted_balance DESC, id), w_grp AS (PARTITION BY status ORDER BY adjusted_balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
